from pathlib import Path
import argparse,hashlib,json
p=argparse.ArgumentParser();p.add_argument('run');a=p.parse_args();base=Path(__file__).parent;raw=(base/'cases.json').read_bytes();assert hashlib.sha256(raw).hexdigest()==json.loads((base/'freeze.json').read_text())['sha256'];cases={x['name']:x for x in json.loads(raw)};d=base/a.run;report=json.loads((d/'report.json').read_text());rows=report['cases'];assert len(rows)==48 and len({(x['name'],x['mode']) for x in rows})==48
positives=[x for x in rows if x['expected']=='repair_build' and x['mode']=='do'];statuses=[x for x in rows if x['expected']=='status' and x['mode']=='do']
def exact_native(x):return x['changed'] and x['exact_repair'] and x['native_exit']==0
s=dict(binary_sha256=report['binary_sha256'],positive_exact_native=sum(exact_native(x) for x in positives),positive_total=8,positive_failed=[x['name'] for x in positives if not exact_native(x)],unrequested_edits=[x['name']+'-'+x['mode'] for x in rows if x['expected']!='repair_build' and x['changed']],negative_command_previews=sum(x['preview_mutating'] for x in rows if x['expected']=='no_mutating_action'),status_correct=sum(x['preview_meanings']==[f"Ask({cases[x['name']]['query']}({x['check']}))"] for x in statuses),status_total=4,status_actual={x['name']:x['preview_meanings'] for x in statuses},ask_apply_unchanged=all(not x['changed'] for x in rows if x['mode']=='ask'))
if a.run!='baseline':
 old=json.loads((base/'baseline/report.json').read_text())['cases'];good={x['name'] for x in old if x['expected']=='repair_build' and x['mode']=='do' and exact_native(x)};s['baseline_good']=len(good);s['baseline_good_retained']=sum(exact_native(x) and x['name'] in good for x in positives);s['all_desired_gates_pass']=s['positive_exact_native']==8 and s['status_correct']==4 and not s['unrequested_edits'] and s['negative_command_previews']==0 and s['ask_apply_unchanged']
q=d/'scored-summary.json';assert not q.exists();q.write_text(json.dumps(s,indent=2)+'\n');print(json.dumps(s,indent=2))
